public void renderQueue(VertexConsumer buffer, Collection<IParticle> particles, Camera camera, float partialTicks) {
        if (renderer.getRenderMode() == ParticleRendererSetting.Mode.None) {
            return;
        }
        ModelPass model = null;
        if (renderer.getRenderMode() == ParticleRendererSetting.Mode.Model) {
            notifyDynamicMesh();
            model = modelPass();
        }
        var records = activeRecords;
        if (records != null) {
            records.setVertsPerParticle(model == null ? 4 : 4 * primitiveCount(model.mesh()));
        }
        for (var particle : particles) {
            if (particle instanceof TileParticle tileParticle && tileParticle.getDelay() <= 0) {
                renderParticle(buffer, tileParticle, camera, partialTicks, model);
                if (records != null) {
                    records.write(tileParticle, partialTicks);
                }
            }
        }
    }

private ModelPass modelPass() {
        var source = renderer.getModelSource();
        var mesh = source.getMesh();
        var animation = source.vertexAnimation();
        // a table baked for a different vertex count would be indexed past its end; the rest pose is the
        // safe reading of "these two disagree"
        boolean usable = animation != null && animation.vertexCount() == mesh.vertexCount();
        return new ModelPass(mesh,
                source.hasAtlasUV() && !renderer.isUseBlockUV() && mesh.spriteBounds().length > 0,
                renderer.isShade(), renderer.getModelPivot(),
                usable ? animation : null, usable ? animation.table() : null);
    }

private void renderParticle(@Nonnull VertexConsumer buffer, TileParticle particle, Camera camera,
                                float partialTicks, @Nullable ModelPass model) {
        var vec3 = camera.getPosition();

        var localPos = particle.getSimPos(partialTicks).mulPosition(particle.getSpaceTransform());
        var x = (float) (localPos.x - vec3.x);
        var y = (float) (localPos.y - vec3.y);
        var z = (float) (localPos.z - vec3.z);

        var color = particle.getRealColor(partialTicks);
        var r = color.x();
        var g = color.y();
        var b = color.z();
        var a = color.w();

        var light = particle.getRealLight(partialTicks);

        var rotation = particle.getRealRotation(partialTicks);
        var renderMode = renderer.getRenderMode();

        var size = particle.getRealSize(partialTicks);

        if (model != null) { // non-null exactly in Model mode; see renderQueue
            // mesh positions are already in centered model space (PhotonMesh convention)
            var transform = new Matrix4f().translate(x, y, z)
                    .rotate(computeModelQuaternion(particle, rotation, camera, partialTicks))
                    .scale(size.mul(particle.getSpaceScale()));
            var mesh = model.mesh();
            // ⚠️ A baked pose table is not only the instanced path's business: GPU instancing is off by
            // default, and without this a per-particle-phase model drew its rest pose and never moved.
            int poseBase = poseBaseFor(model.animation(), particle, partialTicks);
            var table = poseBase < 0 ? null : model.table();
            // the normal matrix depends on the particle, not the face — it used to be rebuilt per quad
            var normalMat = transform.normal(new Matrix3f());
            var indices = mesh.indices();
            int triangle = 0;
            while (triangle < mesh.triangleCount()) {
                int i = triangle * 3;
                int va = indices[i], vb = indices[i + 1], vc = indices[i + 2];
                // ⚠️ a QUADS-mode buffer, so four vertices a primitive: an authored quad goes out
                // whole (its second triangle is (c, d, a)), a lone triangle repeats its last corner
                if (mesh.quadPaired(triangle)) {
                    int vd = indices[i + 4];
                    putMeshVertex(transform, normalMat, buffer, model, table, poseBase, va, r, g, b, a, light);
                    putMeshVertex(transform, normalMat, buffer, model, table, poseBase, vb, r, g, b, a, light);
                    putMeshVertex(transform, normalMat, buffer, model, table, poseBase, vc, r, g, b, a, light);
                    putMeshVertex(transform, normalMat, buffer, model, table, poseBase, vd, r, g, b, a, light);
                    triangle += 2;
                } else {
                    putMeshVertex(transform, normalMat, buffer, model, table, poseBase, va, r, g, b, a, light);
                    putMeshVertex(transform, normalMat, buffer, model, table, poseBase, vb, r, g, b, a, light);
                    putMeshVertex(transform, normalMat, buffer, model, table, poseBase, vc, r, g, b, a, light);
                    putMeshVertex(transform, normalMat, buffer, model, table, poseBase, vc, r, g, b, a, light);
                    triangle++;
                }
            }
        } else {
            Quaternionf quaternion;
            float finalSizeX = size.x;
            float finalSizeY = size.y;
            float finalSizeZ = size.z;
            var spaceScale = particle.getSpaceScale();

            if (renderMode == ParticleRendererSetting.Mode.StretchedBillboard) {
                var frame = computeStretchedFrame(particle, localPos, vec3.x, vec3.y, vec3.z, size, spaceScale);
                quaternion = frame.rotation;
                finalSizeX = frame.stretchedSizeX;
                x -= frame.offsetX;
                y -= frame.offsetY;
                z -= frame.offsetZ;
            } else {
                quaternion = computeBillboardQuaternion(particle, renderMode, camera, partialTicks, rotation);
            }

            var rawVertexes = new Vector3f[]{
                    new Vector3f(1.0F, -1.0F, 0.0F),
                    new Vector3f(1.0F, 1.0F, 0.0F),
                    new Vector3f(-1.0F, 1.0F, 0.0F),
                    new Vector3f(-1.0F, -1.0F, 0.0F),
            };
            var normal = new Vector3f(0, 0, 1);

            for (var i = 0; i < 4; ++i) {
                var vertex = rawVertexes[i];
                vertex.mul(finalSizeX, finalSizeY, finalSizeZ);
                vertex = quaternion.transform(vertex);
                vertex.mul(spaceScale);
                vertex.add(x, y, z);
            }

            normal = quaternion.transform(normal);

            var uvs = particle.getRealUVs(partialTicks);
            var u0 = uvs.x();
            var v0 = uvs.y();
            var u1 = uvs.z();
            var v1 = uvs.w();

            buffer.addVertex(rawVertexes[0].x(), rawVertexes[0].y(), rawVertexes[0].z()).setUv(u1, v1).setColor(r, g, b, a).setLight(light).setNormal(normal.x, normal.y, normal.z);
            buffer.addVertex(rawVertexes[1].x(), rawVertexes[1].y(), rawVertexes[1].z()).setUv(u1, v0).setColor(r, g, b, a).setLight(light).setNormal(normal.x, normal.y, normal.z);
            buffer.addVertex(rawVertexes[2].x(), rawVertexes[2].y(), rawVertexes[2].z()).setUv(u0, v0).setColor(r, g, b, a).setLight(light).setNormal(normal.x, normal.y, normal.z);
            buffer.addVertex(rawVertexes[3].x(), rawVertexes[3].y(), rawVertexes[3].z()).setUv(u0, v1).setColor(r, g, b, a).setLight(light).setNormal(normal.x, normal.y, normal.z);
        }
    }

private void createModelGeometry(InstanceResource resource) {
        var source = renderer.getModelSource();
        var mesh = source.getMesh();
        var remapUV = source.hasAtlasUV() && !builtUseBlockUV && mesh.spriteBounds().length > 0;
        int vertexCount = mesh.vertexCount();

        // ---- geometry: position 3 + normal 3 ----------------------------------------------------
        // ours, or the provider's own buffer bound straight in: a buffer object is untyped in GL, so
        // the SSBO a compute pass wrote is a perfectly good vertex buffer
        var dynamic = dynamic();
        builtGlBuffer = dynamic == null ? 0 : dynamic.glBuffer();
        if (builtGlBuffer != 0) {
            builtGlOffset = dynamic.glByteOffset();
            builtGlPackedNormals = dynamic.glPackedNormals();
            glBindBuffer(GL_ARRAY_BUFFER, builtGlBuffer);
            // packed = 16B a vertex, the layout a compute skinning pass already writes
            int stride = builtGlPackedNormals ? 3 * Float.BYTES + 4 : PhotonMesh.FLOATS_PER_GEOMETRY * Float.BYTES;
            glVertexAttribPointer(0, 3, GL_FLOAT, false, stride, builtGlOffset);
            glEnableVertexAttribArray(0);
            if (builtGlPackedNormals) {
                glVertexAttribPointer(2, 4, GL_BYTE, true, stride, builtGlOffset + 3 * Float.BYTES);
            } else {
                glVertexAttribPointer(2, 3, GL_FLOAT, false, stride, builtGlOffset + 3 * Float.BYTES);
            }
            glEnableVertexAttribArray(2);
        } else {
            builtGlOffset = 0L;
            builtGlPackedNormals = false;
            resource.modelVbo = glGenBuffers();
            glBindBuffer(GL_ARRAY_BUFFER, resource.modelVbo);
            glBufferData(GL_ARRAY_BUFFER, mesh.geometry(), GL_DYNAMIC_DRAW);
            int geometryStride = PhotonMesh.FLOATS_PER_GEOMETRY * Float.BYTES;
            glVertexAttribPointer(0, 3, GL_FLOAT, false, geometryStride, 0);
            glEnableVertexAttribArray(0);
            glVertexAttribPointer(2, 3, GL_FLOAT, false, geometryStride, 3 * Float.BYTES);
            glEnableVertexAttribArray(2);
        }

        // ---- attributes: u, v, shade ------------------------------------------------------------
        var attributes = mesh.attributes();
        var bounds = mesh.spriteBounds();
        var attributeBuffer = BufferUtils.createFloatBuffer(vertexCount * PhotonMesh.FLOATS_PER_ATTRIBUTE);
        for (int vertex = 0; vertex < vertexCount; vertex++) {
            int off = PhotonMesh.attributeOffset(vertex);
            float u = attributes[off];
            float v = attributes[off + 1];
            if (remapUV) {
                int s = PhotonMesh.spriteOffset(vertex);
                float u0 = bounds[s], v0 = bounds[s + 1];
                float uw = bounds[s + 2] - u0, vh = bounds[s + 3] - v0;
                if (uw != 0f) u = (u - u0) / uw;
                if (vh != 0f) v = (v - v0) / vh;
            }
            attributeBuffer.put(u).put(v).put(builtShade ? attributes[off + 2] : 1f);
        }
        attributeBuffer.flip();
        resource.attributeVbo = glGenBuffers();
        glBindBuffer(GL_ARRAY_BUFFER, resource.attributeVbo);
        glBufferData(GL_ARRAY_BUFFER, attributeBuffer, GL_STATIC_DRAW);
        glVertexAttribPointer(1, 3, GL_FLOAT, false, PhotonMesh.FLOATS_PER_ATTRIBUTE * Float.BYTES, 0);
        glEnableVertexAttribArray(1);

        // ⚠️ when off, location 3 must be left DISABLED rather than pointing at a deleted buffer:
        // the enable bit is VAO state and survives a rebuild
        glDisableVertexAttribArray(3);
        if (wantsTangent) {
            resource.tangentVbo = glGenBuffers();
            glBindBuffer(GL_ARRAY_BUFFER, resource.tangentVbo);
            glBufferData(GL_ARRAY_BUFFER, mesh.tangents(), GL_STATIC_DRAW);
            glVertexAttribPointer(3, 4, GL_FLOAT, false, PhotonMesh.FLOATS_PER_TANGENT * Float.BYTES, 0);
            glEnableVertexAttribArray(3);
        }

        // ---- indices ----------------------------------------------------------------------------
        var indices = mesh.indices();
        resource.modelEbo = glGenBuffers();
        glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, resource.modelEbo);
        glBufferData(GL_ELEMENT_ARRAY_BUFFER, indices, GL_STATIC_DRAW);
        modelEboSize = indices.length;
        builtTopology = mesh.topology();
        builtRevision = mesh.geometryRevision();
    }

@Override
    public PhotonMesh getMesh() {
        return PhotonMeshCache.INSTANCE.get(new PhotonMeshCache.JsonKey(modelLocation), k -> bake());
    }

@Nullable
    private PhotonMesh bake() {
        // do not access the model bakery during reloading (null = retry later, not cached)
        if (Minecraft.getInstance().getOverlay() instanceof LoadingOverlay) {
            return null;
        }
        var random = RandomSource.create();
        var bakedModel = ModelFactory.getUnBakedModel(modelLocation).bake(
                ModelFactory.getModelBaker(),
                Material::sprite,
                BlockModelRotation.X0_Y0);
        if (bakedModel == null) {
            bakedModel = ModelFactory.getUnBakedModel(ResourceLocation.withDefaultNamespace("block/stone")).bake(
                    ModelFactory.getModelBaker(),
                    Material::sprite,
                    BlockModelRotation.X0_Y0);
        }
        var quads = new ArrayList<Pair<BakedQuad, Float>>();
        for (var side : TileParticle.MODEL_SIDES) {
            var brightness = side == null ? 1f : switch (side) {
                case DOWN, UP -> 0.9F;
                case NORTH, SOUTH -> 0.8F;
                case WEST, EAST -> 0.6F;
            };
            for (var quad : bakedModel.getQuads(null, side, random, ModelData.EMPTY, null)) {
                quads.add(Pair.of(quad, brightness));
            }
        }
        return PhotonMesh.fromBakedQuads(quads);
    }

public static PhotonMesh fromBakedQuads(List<Pair<BakedQuad, Float>> quads) {
        var builder = new Builder();
        var corners = new float[4][8];
        for (var pair : quads) {
            var quad = pair.getLeft();
            int[] data = quad.getVertices();
            int points = Math.min(data.length / IQuadTransformer.STRIDE, 4);
            if (points < 3) continue;
            for (int k = 0; k < points; k++) {
                int off = k * IQuadTransformer.STRIDE;
                var corner = corners[k];
                corner[0] = Float.intBitsToFloat(data[off + IQuadTransformer.POSITION]) - 0.5f;
                corner[1] = Float.intBitsToFloat(data[off + IQuadTransformer.POSITION + 1]) - 0.5f;
                corner[2] = Float.intBitsToFloat(data[off + IQuadTransformer.POSITION + 2]) - 0.5f;
                corner[3] = Float.intBitsToFloat(data[off + IQuadTransformer.UV0]);
                corner[4] = Float.intBitsToFloat(data[off + IQuadTransformer.UV0 + 1]);
                int packedNormal = data[off + IQuadTransformer.NORMAL];
                corner[5] = ((byte) packedNormal) / 127.0f;
                corner[6] = ((byte) (packedNormal >> 8)) / 127.0f;
                corner[7] = ((byte) (packedNormal >> 16)) / 127.0f;
            }
            var sprite = quad.getSprite();
            if (points == 3) {
                builder.triangle(corners[0], corners[1], corners[2], pair.getRight())
                        .sprite(sprite.getU0(), sprite.getV0(), sprite.getU1(), sprite.getV1());
            } else {
                builder.quad(corners[0], corners[1], corners[2], corners[3], pair.getRight())
                        .sprite(sprite.getU0(), sprite.getV0(), sprite.getU1(), sprite.getV1());
            }
        }
        return builder.build();
    }

public Builder sprite(float u0, float v0, float u1, float v1) {
            if (lastFaceCount == 0) {
                return this;
            }
            anySprite = true;
            for (int i = 0; i < lastFaceCount; i++) {
                int off = spriteOffset(lastFaceStart + i);
                spriteBounds.set(off, u0);
                spriteBounds.set(off + 1, v0);
                spriteBounds.set(off + 2, u1);
                spriteBounds.set(off + 3, v1);
            }
            return this;
        }

public static int geometryOffset(int vertex) {
        return vertex * FLOATS_PER_GEOMETRY;
    }

public static int attributeOffset(int vertex) {
        return vertex * FLOATS_PER_ATTRIBUTE;
    }

public static int spriteOffset(int vertex) {
        return vertex * FLOATS_PER_SPRITE;
    }

@Nullable
    private IModelSource resolveRaw() {
        var meshData = MeshResource.INSTANCE.getResourceInstance().getResource(getResourcePath());
        if (meshData == null) return null;
        var source = meshData.getSource();
        int guard = 0;
        while (source instanceof ResourceMeshSource ref && guard++ < 8) {
            var next = MeshResource.INSTANCE.getResourceInstance().getResource(ref.getResourcePath());
            if (next == null) return null;
            source = next.getSource();
        }
        return source instanceof ResourceMeshSource ? null : source;
    }

@Override
    public PhotonMesh getMesh() {
        var source = resolveRaw();
        return source == null ? PhotonMesh.EMPTY : source.getMesh();
    }

@Override
    public boolean hasAtlasUV() {
        var source = resolveRaw();
        return source != null && source.hasAtlasUV();
    }
